-- Generated by migration new; ordered after existing future-dated R7B files.
-- Additive R7E foundation. No historical event backfill or external invitations.
begin;
create index inquiry_project_history_predecessor on public.inquiry_project_history(request_id,id);
create table public.project_event_history (
 id bigint generated always as identity primary key,
 request_id uuid not null references public.inquiry_projects(request_id) on delete cascade,
 source text not null, action text not null, item_id text,
 actor uuid references auth.users(id) on delete set null,
 recipients uuid[] not null default '{}', details jsonb not null default '{}',
 created_at timestamptz not null default now()
);
create index project_event_history_page on public.project_event_history(request_id,created_at desc,id desc);
alter table public.project_event_history enable row level security;
revoke all on public.project_event_history from public,anon,authenticated,service_role;
grant select on public.project_event_history to authenticated;
create policy project_event_staff_read on public.project_event_history for select to authenticated using((select public.is_inquiry_staff()));

create table public.project_meetings (
 id uuid primary key,
 request_id uuid not null references public.inquiry_projects(request_id) on delete cascade,
 title text not null check(length(btrim(title)) between 1 and 300),
 starts_at timestamptz not null, ends_at timestamptz not null,
 timezone text not null, organizer uuid references auth.users(id) on delete set null,
 attendees uuid[] not null default '{}', status text not null check(status in ('scheduled','cancelled')),
 location text not null default '' check(length(location)<=1000),
 meeting_url text check(meeting_url is null or meeting_url ~ '^https://[^/?#[:space:]@]+([/?#][^[:space:]]*)?$'),
 revision integer not null default 1 check(revision>0),
 updated_at timestamptz not null default now(), updated_by uuid references auth.users(id),
 check(ends_at>starts_at and ends_at-starts_at<=interval '7 days'),
 check(cardinality(attendees)<=50)
);
create index project_meetings_project_page on public.project_meetings(request_id,starts_at,id);
create index project_meetings_organizer on public.project_meetings(organizer);
create index project_meetings_upcoming on public.project_meetings(request_id,ends_at,starts_at,id) where status='scheduled';
alter table public.project_meetings enable row level security;
revoke all on public.project_meetings from public,anon,authenticated,service_role;
grant select on public.project_meetings to authenticated;
create policy project_meeting_staff_read on public.project_meetings for select to authenticated using((select public.is_inquiry_staff()));

create function public.project_meeting_member_eligible(p_request uuid,p_user uuid) returns boolean
language sql stable security definer set search_path='' as $$
 select exists(select 1 from public.inquiry_staff where user_id=p_user and active)
 or public.project_client_member_eligible(p_request,p_user);
$$;
revoke all on function public.project_meeting_member_eligible(uuid,uuid) from public,anon,authenticated,service_role;

create function public.manage_project_meeting(p_request uuid,p_command jsonb) returns jsonb
language plpgsql security definer set search_path='' as $$
declare p public.inquiry_projects%rowtype; m public.project_meetings%rowtype; next_row public.project_meetings%rowtype;
 mid uuid; attendees uuid[]; organizer uuid; start_time timestamptz; end_time timestamptz;
begin
 if auth.uid() is null or not public.is_inquiry_staff() then raise exception 'Staff authorization required' using errcode='42501';end if;
 select * into p from public.inquiry_projects where request_id=p_request for update;
 if not found then return jsonb_build_object('result','not_found');end if;
 if p.state='completed' then return jsonb_build_object('result','locked');end if;
 if p_command->>'action' not in ('save','cancel') or p_command->>'action' is null then raise exception 'Invalid meeting command' using errcode='22023';end if;
 mid:=(p_command->>'id')::uuid;
 select * into m from public.project_meetings where id=mid for update;
 if m.id is not null and m.request_id<>p_request then return jsonb_build_object('result','not_found');end if;
 if coalesce(m.revision,0) is distinct from (p_command->>'expectedRevision')::integer then return jsonb_build_object('result','conflict');end if;
 if p_command->>'action'='cancel' then
   if m.id is null then return jsonb_build_object('result','not_found');end if;
   if m.status='cancelled' then return jsonb_build_object('result','saved','revision',m.revision);end if;
   update public.project_meetings set status='cancelled',revision=revision+1,updated_at=now(),updated_by=auth.uid() where id=mid returning * into next_row;
 else
   if not exists(select 1 from pg_timezone_names where name=p_command->>'timezone') then raise exception 'Choose a valid timezone' using errcode='22023';end if;
   -- Explicit offsets disambiguate fall-back times and avoid session-timezone coercion.
   if p_command->>'startsAt' !~ '(Z|[+-][0-9]{2}:[0-9]{2})$' or p_command->>'endsAt' !~ '(Z|[+-][0-9]{2}:[0-9]{2})$' then raise exception 'Meeting times require an explicit UTC offset' using errcode='22023';end if;
   start_time:=(p_command->>'startsAt')::timestamptz;end_time:=(p_command->>'endsAt')::timestamptz;
   if (start_time at time zone (p_command->>'timezone')) is distinct from left(p_command->>'startsAt',19)::timestamp or (end_time at time zone (p_command->>'timezone')) is distinct from left(p_command->>'endsAt',19)::timestamp then raise exception 'UTC offset does not match this timezone at the meeting time' using errcode='22023';end if;
   organizer:=(p_command->>'organizer')::uuid;
   select coalesce(array_agg(distinct value::uuid),'{}') into attendees from jsonb_array_elements_text(p_command->'attendees');
   if not public.project_meeting_member_eligible(p_request,organizer) or exists(select 1 from unnest(attendees) uid where not public.project_meeting_member_eligible(p_request,uid)) then raise exception 'Choose current eligible project members' using errcode='42501';end if;
   insert into public.project_meetings(id,request_id,title,starts_at,ends_at,timezone,organizer,attendees,status,location,meeting_url,updated_by)
   values(mid,p_request,btrim(p_command->>'title'),start_time,end_time,p_command->>'timezone',organizer,attendees,'scheduled',coalesce(p_command->>'location',''),nullif(p_command->>'meetingUrl',''),auth.uid())
   on conflict(id) do update set title=excluded.title,starts_at=excluded.starts_at,ends_at=excluded.ends_at,timezone=excluded.timezone,organizer=excluded.organizer,attendees=excluded.attendees,status='scheduled',location=excluded.location,meeting_url=excluded.meeting_url,revision=public.project_meetings.revision+1,updated_at=now(),updated_by=auth.uid()
   returning * into next_row;
 end if;
 insert into public.project_event_history(request_id,source,action,item_id,actor,recipients,details)
 values(p_request,'meetings',case when m.id is null then 'created' when next_row.status='cancelled' then 'cancelled' else 'updated' end,mid::text,auth.uid(),next_row.attendees,
 jsonb_build_object('title',next_row.title,'revision',next_row.revision,'startsAt',next_row.starts_at,'endsAt',next_row.ends_at,'timezone',next_row.timezone));
 return jsonb_build_object('result','saved','revision',next_row.revision,'meeting',to_jsonb(next_row));
end;$$;
revoke all on function public.manage_project_meeting(uuid,jsonb) from public,anon,service_role;
grant execute on function public.manage_project_meeting(uuid,jsonb) to authenticated;

-- Capture only actual future changes for sources without immutable history.
create function public.audit_project_delivery_record() returns trigger language plpgsql security definer set search_path='' as $$
begin
 if tg_op='UPDATE' and to_jsonb(new)=to_jsonb(old) then return new;end if;
 insert into public.project_event_history(request_id,source,action,item_id,actor,details)
 values(new.request_id,'delivery',tg_table_name||':'||lower(tg_op),coalesce(to_jsonb(new)->>'item_id',to_jsonb(new)->>'check_id','closeout'),new.updated_by,
 jsonb_build_object('title',coalesce(to_jsonb(new)->>'title','Project closeout'),'revision',new.revision,'status',coalesce(to_jsonb(new)->>'status',to_jsonb(new)->>'release_state')));
 return new;
end;$$;
revoke all on function public.audit_project_delivery_record() from public,anon,authenticated,service_role;
create trigger r7e_handoff_audit after insert or update on public.project_handoff_items for each row execute function public.audit_project_delivery_record();
create trigger r7e_qa_audit after insert or update on public.project_qa_checks for each row execute function public.audit_project_delivery_record();
create trigger r7e_closeout_audit after insert or update on public.project_closeout for each row execute function public.audit_project_delivery_record();

-- Remember the actual submitted task/control version. Existing pending requests
-- remain reviewable explicitly; do not invent a historical submission baseline.
create table public.project_request_baselines (
 response_id uuid primary key references public.project_client_task_responses(id) on delete cascade,
 request_id uuid not null references public.inquiry_projects(request_id) on delete cascade,
 submitted_task jsonb not null,submitted_control_revision integer
);
create index project_request_baselines_project on public.project_request_baselines(request_id,response_id);
alter table public.project_request_baselines enable row level security;
revoke all on public.project_request_baselines from public,anon,authenticated,service_role;
grant select on public.project_request_baselines to authenticated;
create policy request_baseline_staff_read on public.project_request_baselines for select to authenticated using((select public.is_inquiry_staff()));
create function public.capture_project_request_baseline() returns trigger language plpgsql security definer set search_path='' as $$
declare task jsonb; control_revision integer;
begin
 select value into task from public.inquiry_projects p cross join lateral jsonb_array_elements(p.body->'tasks') where p.request_id=new.request_id and value->>'id'=new.task_id;
 select revision into control_revision from public.project_task_controls where request_id=new.request_id and task_id=new.task_id;
 if task is null then raise exception 'Task no longer exists' using errcode='23514';end if;
 insert into public.project_request_baselines(response_id,request_id,submitted_task,submitted_control_revision) values(new.id,new.request_id,task,control_revision);
 return new;
end;$$;
revoke all on function public.capture_project_request_baseline() from public,anon,authenticated,service_role;
create trigger r7e_request_baseline after insert on public.project_client_task_responses for each row execute function public.capture_project_request_baseline();

-- Preserve the proven R7A review transaction; add submission-baseline protection.
alter function public.staff_review_client_task_response(uuid,text,text,integer) rename to staff_review_client_task_response_r7a;
revoke all on function public.staff_review_client_task_response_r7a(uuid,text,text,integer) from public,anon,authenticated,service_role;
create function public.staff_review_client_task_response(p_response uuid,p_action text,p_note text,p_revision integer) returns jsonb
language plpgsql security definer set search_path='' as $$
declare r public.project_client_task_responses%rowtype; b public.project_request_baselines%rowtype; p public.inquiry_projects%rowtype; current_task jsonb; control_revision integer;
begin
 if auth.uid() is null or not public.is_inquiry_staff() then raise exception 'Staff required' using errcode='42501';end if;
 if p_action is null or p_action not in ('accept','reject') or p_note is null or length(p_note)>2000 or p_revision is null or p_revision<1 then raise exception 'Invalid review action' using errcode='22023';end if;
 select * into r from public.project_client_task_responses where id=p_response;
 if r.id is null then return jsonb_build_object('result','not_found');end if;
 select * into p from public.inquiry_projects where request_id=r.request_id for update;
 select * into r from public.project_client_task_responses where id=p_response for update;
 if r.status<>'pending' then return jsonb_build_object('result','already_reviewed');end if;
 if p.revision is distinct from p_revision then return jsonb_build_object('result','conflict');end if;
 if p.state='completed' then return jsonb_build_object('result','locked');end if;
 if p_action='reject' then
  update public.project_client_task_responses set status='rejected',reviewed_by=auth.uid(),reviewed_at=now(),review_note=btrim(p_note) where id=r.id;
  return jsonb_build_object('result','saved','projectRevision',p.revision);
 end if;
 if p_action='accept' then
  select * into b from public.project_request_baselines where response_id=r.id and request_id=r.request_id;
  select value into current_task from jsonb_array_elements(p.body->'tasks') where value->>'id'=r.task_id;
  select revision into control_revision from public.project_task_controls where request_id=r.request_id and task_id=r.task_id;
  if b.submitted_task is null then return jsonb_build_object('result','baseline_missing');end if;
  if b.submitted_task is distinct from current_task or b.submitted_control_revision is distinct from control_revision then return jsonb_build_object('result','stale');end if;
 end if;
 return public.staff_review_client_task_response_r7a(p_response,p_action,p_note,p_revision);
end;$$;
revoke all on function public.staff_review_client_task_response(uuid,text,text,integer) from public,anon,service_role;
grant execute on function public.staff_review_client_task_response(uuid,text,text,integer) to authenticated;

alter table public.project_communication_outbox add column first_attempt_at timestamptz;
alter table public.project_communication_outbox drop constraint project_communication_outbox_kind_check;
alter table public.project_communication_outbox add constraint project_communication_outbox_kind_check check(kind in ('inquiry_acknowledgement','workspace_invitation','workspace_access','onboarding_action','onboarding_deadline','brief_review','project_review','deliverable_review','change_review','release_ready','project_complete','task_deadline','task_assignment','task_request','task_decision','approval_decision'));
alter table public.project_communication_outbox drop constraint project_communication_outbox_action_surface_check;
alter table public.project_communication_outbox add constraint project_communication_outbox_action_surface_check check(action_surface in ('public','client','staff'));

-- One durable existing outbox, shared by email and the established staff inbox.
create function public.project_signal_url_component(value text) returns text
language sql immutable set search_path='' as $$
 select coalesce(string_agg(case when chr(get_byte(convert_to(value,'UTF8'),n)) ~ '^[A-Za-z0-9_.~-]$' then chr(get_byte(convert_to(value,'UTF8'),n)) else '%'||lpad(to_hex(get_byte(convert_to(value,'UTF8'),n)),2,'0') end,'' order by n),'') from generate_series(0,octet_length(convert_to(value,'UTF8'))-1) n;
$$;
revoke all on function public.project_signal_url_component(text) from public,anon,authenticated,service_role;
create function public.queue_project_signal(p_request uuid,p_key text,p_kind text,p_users uuid[],p_meta jsonb,p_category text default 'approvals') returns void
language plpgsql security definer set search_path='' as $$
declare uid uuid; is_staff boolean; target text;
begin
 foreach uid in array p_users loop
  select exists(select 1 from public.inquiry_staff where user_id=uid and active) into is_staff;
  if not public.project_meeting_member_eligible(p_request,uid) then continue;end if;
  if is_staff and not coalesce((select case p_category when 'tasks' then tasks else approvals end from public.staff_notification_preferences where user_id=uid),true) then continue;end if;
  target:='/projects/'||p_request::text||case when p_kind in ('task_request','task_decision') then '?tab=requests&request='||(p_meta->>'responseId') when p_meta ? 'taskId' then '?tab=plan&task='||public.project_signal_url_component(p_meta->>'taskId') when p_kind in ('deliverable_review','change_review') or p_meta->>'source' in ('project_deliverable_versions','project_change_requests') then '?tab=delivery' when p_kind='project_review' or p_meta->>'source' in ('project_publications','project_client_reviews') then '/publish' else '?tab=brief' end;
  if not is_staff then target:='/projects/'||p_request::text||case when p_meta ? 'responseId' then '?request='||(p_meta->>'responseId') else '' end;end if;
  insert into public.project_communication_outbox(request_id,recipient_user_id,recipient_email,kind,dedupe_key,subject,body_text,action_surface,action_path,metadata)
  select p_request,uid,u.email,p_kind,p_key||':'||uid::text,
   case p_kind when 'task_assignment' then 'A Bivi task was assigned to you' when 'task_request' then 'A client task request needs review' when 'task_decision' then 'Bivi reviewed your task request' when 'approval_decision' then 'A project approval decision was recorded' else 'A Bivi project approval needs review' end,
   'Open Bivi to review this project update. Sign in to see the information you are authorized to access.',
   case when is_staff then 'staff' else 'client' end,target,p_meta||jsonb_build_object('category',p_category,'actor',auth.uid())
  from auth.users u where u.id=uid and u.email is not null and length(btrim(u.email)) between 3 and 254
  on conflict(dedupe_key) do nothing;
 end loop;
end;$$;
revoke all on function public.queue_project_signal(uuid,text,text,uuid[],jsonb,text) from public,anon,authenticated,service_role;

create function public.project_communication_allowed(p_id uuid) returns boolean
language sql stable security definer set search_path='' as $$
 select exists(select 1 from public.project_communication_outbox o join auth.users u on u.id=o.recipient_user_id
 where o.id=p_id and u.email=o.recipient_email
 and (o.kind<>'task_assignment' or exists(select 1 from public.inquiry_projects p cross join lateral jsonb_array_elements(p.body->'tasks') t where p.request_id=o.request_id and t->>'id'=o.metadata->>'taskId' and t->>'status'<>'done'))
 and (o.kind<>'task_request' or exists(select 1 from public.project_client_task_responses r where r.id=(o.metadata->>'responseId')::uuid and r.request_id=o.request_id and r.status='pending'))
 and (o.kind<>'task_decision' or exists(select 1 from public.project_client_task_responses r where r.id=(o.metadata->>'responseId')::uuid and r.request_id=o.request_id and r.submitted_by=u.id and r.status<>'pending'))
 and (o.kind<>'brief_review' or exists(select 1 from public.project_brief_versions v where v.request_id=o.request_id and v.status='pending' and o.dedupe_key='brief_review:v'||v.version||':'||u.id))
 and (o.kind<>'deliverable_review' or exists(select 1 from public.project_deliverable_versions v where v.request_id=o.request_id and v.status='pending_review' and o.dedupe_key='deliverable_review:'||v.deliverable_id||':v'||v.version||':'||u.id))
 and (o.kind<>'change_review' or exists(select 1 from public.project_change_requests v where v.request_id=o.request_id and v.state='proposed' and o.dedupe_key='change_review:'||v.id||':r'||v.revision||':'||u.id))
 and (o.kind<>'project_review' or exists(select 1 from public.project_publications v where v.request_id=o.request_id and not v.withdrawn and coalesce((v.body->>'reviewRequested')::boolean,false) and o.dedupe_key='project_review:v'||v.version||':'||u.id and not exists(select 1 from public.project_client_reviews r where r.request_id=v.request_id and r.version=v.version and r.user_id=u.id)))
 and (
  (o.action_surface='staff' and exists(select 1 from public.inquiry_staff s where s.user_id=u.id and s.active)
   and coalesce((select case when o.metadata->>'category'='tasks' then tasks else approvals end from public.staff_notification_preferences where user_id=u.id),true)
   and (o.kind<>'task_assignment' or exists(select 1 from public.project_task_members tm where tm.request_id=o.request_id and tm.task_id=o.metadata->>'taskId' and tm.user_id=u.id and tm.side='bivi')))
  or (o.action_surface='client' and public.project_client_member_eligible(o.request_id,u.id)
   and (o.kind not in ('brief_review','project_review','deliverable_review','change_review') or exists(select 1 from public.project_clients pc where pc.request_id=o.request_id and pc.user_id=u.id and pc.active and pc.can_review))
   and (o.kind<>'task_assignment' or exists(select 1 from public.project_task_members tm where tm.request_id=o.request_id and tm.task_id=o.metadata->>'taskId' and tm.user_id=u.id and tm.side='client')))
  or (o.kind='workspace_invitation' and exists(select 1 from public.project_clients pc where pc.request_id=o.request_id and pc.user_id=u.id and pc.active))
 )) or exists(select 1 from public.project_communication_outbox o where o.id=p_id and o.kind='inquiry_acknowledgement');
$$;
revoke all on function public.project_communication_allowed(uuid) from public,anon,authenticated;
grant execute on function public.project_communication_allowed(uuid) to service_role;

create function public.queue_project_request_signal() returns trigger language plpgsql security definer set search_path='' as $$
declare recipients uuid[];
begin
 if tg_op='INSERT' then
  select coalesce(array_agg(user_id),'{}') into recipients from public.inquiry_staff where active;
  perform public.queue_project_signal(new.request_id,'task_request:'||new.id,'task_request',recipients,jsonb_build_object('responseId',new.id,'taskId',new.task_id));
 elsif old.status='pending' and new.status<>'pending' then
  perform public.queue_project_signal(new.request_id,'task_decision:'||new.id,'task_decision',array[new.submitted_by],jsonb_build_object('responseId',new.id,'taskId',new.task_id,'decision',new.status));
 end if;
 return new;
end;$$;
revoke all on function public.queue_project_request_signal() from public,anon,authenticated,service_role;
create trigger r7e_request_intent after insert or update of status on public.project_client_task_responses for each row execute function public.queue_project_request_signal();

create function public.queue_project_assignment_signal() returns trigger language plpgsql security definer set search_path='' as $$
begin
 if exists(select 1 from public.project_assignment_events e where e.request_id=new.request_id and e.task_id=new.task_id and e.created_at=new.added_at and e.before_state->'users' @> to_jsonb(array[new.user_id])) then return new;end if;
 perform public.queue_project_signal(new.request_id,'task_assignment:'||new.request_id||':'||md5(new.task_id)||':'||new.user_id||':'||new.added_at::text,'task_assignment',array[new.user_id],jsonb_build_object('taskId',new.task_id),'tasks');
 return new;
end;$$;
revoke all on function public.queue_project_assignment_signal() from public,anon,authenticated,service_role;
create constraint trigger r7e_assignment_intent after insert on public.project_task_members deferrable initially deferred for each row execute function public.queue_project_assignment_signal();

create function public.audit_project_communication() returns trigger language plpgsql security definer set search_path='' as $$
begin
 if new.request_id is null or not exists(select 1 from public.inquiry_projects where request_id=new.request_id) then return new;end if;
 if tg_op='UPDATE' and new.status=old.status and new.attempts=old.attempts and new.last_error=old.last_error then return new;end if;
 insert into public.project_event_history(request_id,source,action,item_id,actor,recipients,details)
 values(new.request_id,'communications',case when new.last_error<>'' and new.status='queued' then 'retry_queued' else new.status end,new.id::text,
 case when tg_op='INSERT' then auth.uid() else null end,array_remove(array[new.recipient_user_id],null),
 jsonb_build_object('kind',new.kind,'attempt',new.attempts,'providerAccepted',new.status='sent','responseId',new.metadata->>'responseId','taskId',new.metadata->>'taskId'));
 return new;
end;$$;
revoke all on function public.audit_project_communication() from public,anon,authenticated,service_role;
create trigger r7e_communication_audit after insert or update on public.project_communication_outbox for each row execute function public.audit_project_communication();

-- Recheck before claiming AND immediately before transport. Revoked recipients
-- are cancelled rather than retried or exposed via notification previews.
create or replace function public.claim_project_communications(p_limit integer default 20,p_request_id uuid default null)
returns setof public.project_communication_outbox language plpgsql security definer set search_path='' as $$
begin
 update public.project_communication_outbox set status='failed',last_error='Provider idempotency window requires manual reconciliation',updated_at=now() where status in ('queued','sending') and attempts>0 and coalesce(first_attempt_at,claimed_at,created_at)<now()-interval '23 hours';
 update public.project_communication_outbox set status='cancelled',updated_at=now() where status in ('queued','sending') and not public.project_communication_allowed(id);
 update public.project_communication_outbox set status='queued',claimed_at=null,next_attempt_at=now(),updated_at=now() where status='sending' and claimed_at<now()-interval '15 minutes' and attempts<max_attempts;
 update public.project_communication_outbox set status='failed',updated_at=now() where status='sending' and claimed_at<now()-interval '15 minutes' and attempts>=max_attempts;
 return query with picked as (
  select id from public.project_communication_outbox where status='queued' and next_attempt_at<=now() and attempts<max_attempts and (p_request_id is null or request_id=p_request_id)
  order by next_attempt_at,created_at,id for update skip locked limit greatest(1,least(coalesce(p_limit,20),50))
 ) update public.project_communication_outbox o set status='sending',attempts=o.attempts+1,first_attempt_at=coalesce(o.first_attempt_at,now()),claimed_at=now(),updated_at=now() from picked where o.id=picked.id returning o.*;
end;$$;

-- Expose safe per-recipient signals through the existing inbox, never the outbox.
create function public.staff_project_signal_notifications() returns table(event_key text,category text,title text,detail text,project_title text,request_id uuid,task_id text,kind text,source_id text,version integer,needs_reviewer boolean,due_on date,occurred_at timestamptz)
language sql stable security definer set search_path='' as $$
 select 'signal:'||o.id,coalesce(o.metadata->>'category','approvals'),o.subject,'Open the authorized project context.',coalesce(p.body->>'title','Project'),o.request_id,null::text,
 null::text,o.action_path,null::integer,false,null::date,o.created_at
 from public.project_communication_outbox o join public.inquiry_projects p on p.request_id=o.request_id
 where auth.uid() is not null and public.is_inquiry_staff() and o.recipient_user_id=auth.uid() and o.action_surface='staff'
 and o.kind in ('task_request','task_decision','approval_decision') and public.project_communication_allowed(o.id)
 and (o.kind<>'task_request' or exists(select 1 from public.project_client_task_responses r where r.id=(o.metadata->>'responseId')::uuid and r.status='pending'));
$$;
revoke all on function public.staff_project_signal_notifications() from public,anon,service_role;
grant execute on function public.staff_project_signal_notifications() to authenticated;
-- Append to the existing actionable view; read/unread and preference views remain.
create or replace view public.staff_notification_events with(security_invoker=true) as
with preferences as (
 select coalesce((select timezone from public.staff_notification_preferences where user_id=auth.uid()),'America/Chicago') as timezone
),clock as (
 select (now() at time zone case when exists(select 1 from pg_timezone_names z where z.name=p.timezone) then p.timezone else 'America/Chicago' end)::date as today from preferences p
)
select 'task:'||t.request_id||':'||md5(t.task_id) as event_key,'tasks'::text as category,
 'Task assigned to you'::text as title,t.title as detail,t.project_title,t.request_id,t.task_id,
 null::text as kind,null::text as source_id,null::integer as version,false as needs_reviewer,
 t.due_on,t.updated_at as occurred_at
from public.staff_my_tasks t where t.task_status<>'done' and t.project_state<>'completed'
union all
select 'deadline:'||t.request_id||':'||md5(t.task_id)||':'||t.due_on||':'||case when t.due_on<c.today then 'overdue' when t.due_on=c.today then 'today' else 'upcoming' end, 'deadlines',
 case when t.due_on<c.today then 'Task overdue' when t.due_on=c.today then 'Task due today' else 'Task due soon' end,
 t.title,t.project_title,t.request_id,t.task_id,null,null,null,false,t.due_on,t.updated_at
from public.staff_my_tasks t cross join clock c where t.task_status<>'done' and t.project_state<>'completed' and t.due_on<=c.today+7
union all
select 'approval:'||a.approval_key||':'||a.source_status||':'||a.needs_reviewer,'approvals',
 a.action_label,a.title,a.project_title,a.request_id,null,a.kind,a.source_id,a.version,a.needs_reviewer,null,a.updated_at
from public.staff_approvals a where a.waiting_on='staff'
union all select * from public.staff_project_signal_notifications();

create function public.queue_project_approval_signal() returns trigger language plpgsql security definer set search_path='' as $$
declare r jsonb:=to_jsonb(new); before_row jsonb:=case when tg_op='UPDATE' then to_jsonb(old) else '{}'::jsonb end;
 users uuid[]; kind text; key text; pending boolean;
begin
 kind:=case tg_table_name when 'project_brief_versions' then 'brief_review' when 'project_deliverable_versions' then 'deliverable_review' when 'project_change_requests' then 'change_review' else 'project_review' end;
 key:=case tg_table_name when 'project_change_requests' then (r->>'id')||':r'||(r->>'revision') when 'project_deliverable_versions' then (r->>'deliverable_id')||':v'||(r->>'version') else 'v'||(r->>'version') end;
 pending:=case tg_table_name when 'project_brief_versions' then (r->>'status')='pending' when 'project_deliverable_versions' then (r->>'status')='pending_review' when 'project_change_requests' then (r->>'state')='proposed' when 'project_publications' then coalesce((r->'body'->>'reviewRequested')::boolean,false) else false end;
 if pending and (tg_op='INSERT' or before_row->>'status' is distinct from (r->>'status') or before_row->>'state' is distinct from (r->>'state')) then
  select coalesce(array_agg(pc.user_id),'{}') into users from public.project_clients pc where pc.request_id=new.request_id and pc.active and pc.can_review;
  perform public.queue_project_signal(new.request_id,kind||':'||key,kind,users,jsonb_build_object('source',tg_table_name,'sourceId',key));
 end if;
 if (((r->>'decided_at') is not null and before_row->>'decided_at' is distinct from (r->>'decided_at')) or (tg_table_name='project_client_reviews' and tg_op='INSERT')) then
  select coalesce(array_agg(user_id),'{}') into users from public.inquiry_staff where active;
  perform public.queue_project_signal(new.request_id,'approval_decision:'||tg_table_name||':'||key||':'||coalesce((r->>'decided_by'),(r->>'user_id'),'account'),'approval_decision',users,jsonb_build_object('source',tg_table_name,'sourceId',key));
 end if;
 return new;
end;$$;
revoke all on function public.queue_project_approval_signal() from public,anon,authenticated,service_role;
create trigger r7e_brief_intent after insert or update on public.project_brief_versions for each row execute function public.queue_project_approval_signal();
create trigger r7e_deliverable_intent after insert or update on public.project_deliverable_versions for each row execute function public.queue_project_approval_signal();
create trigger r7e_change_intent after insert or update on public.project_change_requests for each row execute function public.queue_project_approval_signal();
create trigger r7e_publication_intent after insert on public.project_publications for each row execute function public.queue_project_approval_signal();
create trigger r7e_publication_decision_intent after insert on public.project_client_reviews for each row execute function public.queue_project_approval_signal();

-- Record only recipients actually eligible at future share time; historical NULL
-- explicitly means unknown, never all of today's project members.
alter table public.project_file_history add column recipient_ids uuid[];
create function public.capture_project_file_recipients() returns trigger language plpgsql security definer set search_path='' as $$
begin
 if new.action='share' then select coalesce(array_agg(pc.user_id),'{}') into new.recipient_ids from public.project_clients pc where pc.request_id=new.request_id and pc.active and public.project_client_member_eligible(new.request_id,pc.user_id);end if;
 return new;
end;$$;
revoke all on function public.capture_project_file_recipients() from public,anon,authenticated,service_role;
create trigger r7e_file_share_recipients before insert on public.project_file_history for each row execute function public.capture_project_file_recipients();
create function public.staff_project_activity_page(p_request uuid,p_before_at timestamptz default null,p_before_key text default null,p_limit integer default 25,p_task text default null) returns jsonb
language plpgsql stable security definer set search_path='' as $$
declare result jsonb; people jsonb; last_row jsonb; more boolean; page_size integer:=greatest(1,least(coalesce(p_limit,25),50));
begin
 if auth.uid() is null or not public.is_inquiry_staff() then raise exception 'Staff authorization required' using errcode='42501';end if;
 if not exists(select 1 from public.inquiry_projects where request_id=p_request) then raise exception 'Project not found' using errcode='22023';end if;
 if (p_before_at is null)<>(p_before_key is null) then raise exception 'Invalid activity cursor' using errcode='22023';end if;
 with sources as (
select 'project'::text source_key,'project:'||id::text row_key,created_at occurred_at,to_jsonb(h) payload from (select x.*,lag(snapshot) over(order by id) previous_snapshot from public.inquiry_project_history x where request_id=p_request) h where action<>'save' or (previous_snapshot is not null and snapshot->'body' is distinct from previous_snapshot->'body')
union all
select 'phases'::text source_key,'phases:'||(id)::text row_key,h.created_at occurred_at,to_jsonb(h) payload from public.project_phase_status_history h where h.request_id=p_request and (true)
union all
select 'phase_colors'::text source_key,'phase_colors:'||(id)::text row_key,h.created_at occurred_at,to_jsonb(h) payload from public.project_phase_color_history h where h.request_id=p_request and (true)
union all
select 'hierarchy'::text source_key,'hierarchy:'||(id)::text row_key,h.created_at occurred_at,to_jsonb(h) payload from public.project_hierarchy_history h where h.request_id=p_request and (true)
union all
select 'members'::text source_key,'members:'||(id)::text row_key,h.created_at occurred_at,to_jsonb(h) payload from public.project_assignment_events h where h.request_id=p_request and (true)
union all
select 'tasks'::text source_key,'tasks:'||(id)::text row_key,h.created_at occurred_at,to_jsonb(h) payload from public.project_task_history h where h.request_id=p_request and h.action<>'seed' and not coalesce((
 (h.snapshot->>'change'='start_date' and exists(select 1 from public.project_task_schedule_history q where q.request_id=h.request_id and q.task_id=h.task_id and q.created_at=h.created_at))
 or (h.snapshot->>'change'='bulk_status' and exists(select 1 from public.inquiry_project_history q where q.request_id=h.request_id and q.created_at=h.created_at and q.snapshot->>'revision'=h.snapshot->>'revision'))
 or (h.snapshot->>'change' in ('staff_assignment','staff_deactivated') and exists(select 1 from public.project_assignment_events q where q.request_id=h.request_id and q.task_id=h.task_id and q.created_at=h.created_at))
 ),false)
union all
select 'files'::text source_key,'files:'||(id)::text row_key,h.created_at occurred_at,to_jsonb(h) payload from public.project_file_history h where h.request_id=p_request and (true)
union all
select 'discussion'::text source_key,'discussion:'||(id)::text row_key,h.created_at occurred_at,to_jsonb(h) payload from public.project_comment_history h where h.request_id=p_request and (true)
union all
select 'task_notes'::text source_key,'task_notes:'||(id)::text row_key,h.created_at occurred_at,to_jsonb(h) payload from public.project_task_note_history h where h.request_id=p_request and (true)
union all
select 'task_files'::text source_key,'task_files:'||(id)::text row_key,h.created_at occurred_at,to_jsonb(h) payload from public.project_task_file_history h where h.request_id=p_request and (true)
union all
select 'access'::text source_key,'access:'||(id)::text row_key,h.created_at occurred_at,to_jsonb(h) payload from public.project_access_history h where h.request_id=p_request and (true)
union all
select 'policies'::text source_key,'policies:'||(id)::text row_key,h.created_at occurred_at,to_jsonb(h) payload from public.project_task_client_policy_history h where h.request_id=p_request and (true)
union all
select 'schedule'::text source_key,'schedule:'||(id)::text row_key,h.created_at occurred_at,to_jsonb(h) payload from public.project_task_schedule_history h where h.request_id=p_request and (true)
union all
select 'lifecycle'::text source_key,'lifecycle:'||(id)::text row_key,h.created_at occurred_at,to_jsonb(h) payload from public.project_lifecycle_history h where h.request_id=p_request and (true)
union all
select 'readiness'::text source_key,'readiness:'||(id)::text row_key,h.created_at occurred_at,to_jsonb(h) payload from public.inquiry_readiness_history h where h.request_id=p_request and (true)
union all
select 'changes'::text source_key,'changes:'||(id)::text row_key,h.created_at occurred_at,to_jsonb(h) payload from public.project_change_request_history h where h.request_id=p_request and (true)
union all
select 'onboarding'::text source_key,'onboarding:'||(id)::text row_key,h.created_at occurred_at,to_jsonb(h) payload from public.inquiry_onboarding_item_history h where h.request_id=p_request and (true)
union all
select 'domain'::text source_key,'domain:'||(id)::text row_key,h.created_at occurred_at,to_jsonb(h) payload from public.project_event_history h where h.request_id=p_request and (true)
union all
select 'clients'::text source_key,'clients:'||(id)::text row_key,h.submitted_at occurred_at,to_jsonb(h)-'reviewed_at' payload from public.project_client_task_responses h where h.request_id=p_request and (true)
union all
select 'clients'::text source_key,'clients:'||(id::text||':reviewed')::text row_key,h.reviewed_at occurred_at,to_jsonb(h)-'submitted_at' payload from public.project_client_task_responses h where h.request_id=p_request and (h.reviewed_at is not null)
union all
select 'brief'::text source_key,'brief:'||(version)::text row_key,h.published_at occurred_at,to_jsonb(h)-'decided_at' payload from public.project_brief_versions h where h.request_id=p_request and (true)
union all
select 'brief'::text source_key,'brief:'||(version::text||':decision')::text row_key,h.decided_at occurred_at,to_jsonb(h)-'published_at' payload from public.project_brief_versions h where h.request_id=p_request and (h.decided_at is not null)
union all
select 'deliverables'::text source_key,'deliverables:'||(deliverable_id||':'||version)::text row_key,h.created_at occurred_at,to_jsonb(h)-'decided_at' payload from public.project_deliverable_versions h where h.request_id=p_request and (true)
union all
select 'deliverables'::text source_key,'deliverables:'||(deliverable_id||':'||version||':decision')::text row_key,h.decided_at occurred_at,to_jsonb(h)-'created_at' payload from public.project_deliverable_versions h where h.request_id=p_request and (h.decided_at is not null)
union all
select 'publishing'::text source_key,'publishing:'||(version)::text row_key,h.created_at occurred_at,to_jsonb(h)-'withdrawn_at' payload from public.project_publications h where h.request_id=p_request and (true)
union all
select 'publishing'::text source_key,'publishing:'||(version::text||':withdrawn')::text row_key,h.withdrawn_at occurred_at,to_jsonb(h)-'created_at' payload from public.project_publications h where h.request_id=p_request and (h.withdrawn_at is not null)
union all
select 'publication_reviews'::text source_key,'publication_reviews:'||(version::text||':'||user_id)::text row_key,h.created_at occurred_at,to_jsonb(h) payload from public.project_client_reviews h where h.request_id=p_request and (true)
union all
select 'legacy_queue'::text source_key,'legacy_queue:'||(id)::text row_key,h.created_at occurred_at,jsonb_build_object('id',h.id,'kind',h.kind,'actor',h.metadata->>'actor','recipient',h.recipient_user_id,'status','queued','created_at',h.created_at) payload from public.project_communication_outbox h where h.request_id=p_request and (not exists(select 1 from public.project_event_history e where e.request_id=p_request and e.source='communications' and e.item_id=h.id::text and e.action='queued' and (e.details->>'attempt')::int=0))
union all
select 'legacy_queue'::text source_key,'legacy_queue:'||(id::text||':sent')::text row_key,h.sent_at occurred_at,jsonb_build_object('id',h.id::text||':sent','kind',h.kind,'recipient',h.recipient_user_id,'status','sent','created_at',h.sent_at) payload from public.project_communication_outbox h where h.request_id=p_request and (h.sent_at is not null and not exists(select 1 from public.project_event_history e where e.request_id=p_request and e.source='communications' and e.item_id=h.id::text and e.action='sent'))
 ), candidates as (
 select * from sources where occurred_at is not null and (p_task is null or payload->>'task_id'=p_task or payload->'details'->>'taskId'=p_task or payload->'metadata'->>'taskId'=p_task or (source_key='project' and exists(select 1 from jsonb_array_elements(coalesce(payload->'snapshot'->'body'->'tasks','[]')||coalesce(payload->'previous_snapshot'->'body'->'tasks','[]')) t where t->>'id'=p_task))) and (p_before_at is null or (occurred_at,row_key)<(p_before_at,p_before_key))
 order by occurred_at desc,row_key desc limit page_size+1
 ), numbered as (select *,row_number() over(order by occurred_at desc,row_key desc) n from candidates)
 select coalesce(jsonb_agg(jsonb_build_object('source',source_key,'key',row_key,'at',occurred_at,'payload',payload) order by occurred_at desc,row_key desc) filter(where n<=page_size),'[]'::jsonb),coalesce(bool_or(n>page_size),false) into result,more from numbered;
 last_row:=result->(jsonb_array_length(result)-1);
 with actor_ids as (
 select distinct nullif(v,'')::uuid uid from jsonb_array_elements(result) item cross join lateral jsonb_each_text(item->'payload') fields(k,v)
 where k in ('actor','actor_id','submitted_by','reviewed_by','published_by','decided_by','created_by','user_id','recipient') and v ~ '^[0-9a-fA-F-]{36}$'
 union select recipients.uid::uuid from jsonb_array_elements(result) item cross join lateral jsonb_array_elements_text(coalesce(nullif(item->'payload'->'recipients','null'::jsonb),nullif(item->'payload'->'recipient_ids','null'::jsonb),'[]'::jsonb)) recipients(uid)
 )
 select coalesce(jsonb_agg(jsonb_build_object('id',a.uid,'label',coalesce(nullif(btrim(concat_ws(' ',cp.first_name,cp.last_name)),''),nullif(u.raw_user_meta_data->>'full_name',''),u.email,'Former account'),
 'kind',case when st.user_id is not null then 'staff' when cp.user_id is not null then 'client' else null end,'avatarPath',coalesce(st.avatar_path,cp.avatar_path))),'[]') into people
 from actor_ids a left join auth.users u on u.id=a.uid left join public.inquiry_staff st on st.user_id=a.uid left join public.client_profiles cp on cp.user_id=a.uid;
 return jsonb_build_object('rows',result,'actors',people,'next',case when more then jsonb_build_object('at',last_row->>'at','key',last_row->>'key') else null end);
end;$$;
revoke all on function public.staff_project_activity_page(uuid,timestamptz,text,integer,text) from public,anon,service_role;
grant execute on function public.staff_project_activity_page(uuid,timestamptz,text,integer,text) to authenticated;

create or replace view public.staff_calendar with(security_invoker=true) as
select events.*,
 array(
  select tm.user_id from public.project_task_members tm
  where events.event_type in ('task','task_start') and tm.request_id=events.request_id and tm.task_id=events.source_id and tm.side='bivi'
  union
  select events.assigned_staff_id where events.assigned_staff_id is not null
   and not exists(select 1 from public.project_task_members tm where tm.request_id=events.request_id and tm.task_id=events.source_id and tm.side='bivi')
 ) as assignee_ids,null::timestamptz starts_at,null::timestamptz ends_at,null::text meeting_timezone
from (
select 'task:'||p.request_id||':'||md5(t.value->>'id') as event_key,
 'task'::text as event_type,p.request_id,t.value->>'id' as source_id,
 t.value->>'title' as title,(t.value->>'dueOn')::date as due_on,
 t.value->>'status' as status,t.value->>'status'='done' as is_done,
 coalesce(p.body->>'title','Project') as project_title,p.public_id as project_public_id,p.state as project_state,
 c.assigned_staff_id,c.owner_type
from public.inquiry_projects p
cross join lateral jsonb_array_elements(p.body->'tasks') t(value)
left join public.project_task_controls c on c.request_id=p.request_id and c.task_id=t.value->>'id'
where (select public.is_inquiry_staff()) and t.value->>'dueOn' is not null
union all
select 'milestone:'||p.request_id||':'||md5(m.value->>'id'),
 'milestone',p.request_id,m.value->>'id',m.value->>'title',(m.value->>'dueOn')::date,
 m.value->>'status',m.value->>'status'='done',coalesce(p.body->>'title','Project'),p.public_id,p.state,
 null::uuid,null::text
from public.inquiry_projects p
cross join lateral jsonb_array_elements(p.body->'milestones') m(value)
where (select public.is_inquiry_staff()) and m.value->>'dueOn' is not null
union all
select 'task-start:'||p.request_id||':'||md5(t.value->>'id'),
 'task_start',p.request_id,t.value->>'id',t.value->>'title',s.start_on,
 t.value->>'status',t.value->>'status'='done',coalesce(p.body->>'title','Project'),p.public_id,p.state,
 c.assigned_staff_id,c.owner_type
from public.project_task_schedule s
join public.inquiry_projects p on p.request_id=s.request_id
join public.project_task_controls c on c.request_id=s.request_id and c.task_id=s.task_id
cross join lateral jsonb_array_elements(p.body->'tasks') t(value)
where (select public.is_inquiry_staff()) and s.start_on is not null and t.value->>'id'=s.task_id
) events
union all
select 'meeting:'||m.id,'meeting',m.request_id,m.id::text,m.title,(m.starts_at at time zone m.timezone)::date,m.status,m.status='cancelled',coalesce(p.body->>'title','Project'),p.public_id,p.state,m.organizer,'meeting',
 array(select distinct uid from unnest(m.attendees||array[m.organizer]) uid where uid is not null),m.starts_at,m.ends_at,m.timezone
from public.project_meetings m join public.inquiry_projects p on p.request_id=m.request_id
where (select public.is_inquiry_staff());
create function public.staff_calendar_in_timezone(p_timezone text,p_from date default null,p_to date default null) returns setof public.staff_calendar
language plpgsql stable security invoker set search_path='' as $$
begin
 if not public.is_inquiry_staff() then raise exception 'Staff authorization required' using errcode='42501';end if;
 if not exists(select 1 from pg_timezone_names where name=p_timezone) then raise exception 'Invalid timezone' using errcode='22023';end if;
 return query select (jsonb_populate_record(null::public.staff_calendar,to_jsonb(c)||case when c.starts_at is not null then jsonb_build_object('due_on',greatest((c.starts_at at time zone p_timezone)::date,case when c.ends_at>(p_from::timestamp at time zone p_timezone) then p_from else null end)) else '{}'::jsonb end)).* from public.staff_calendar c;
end;$$;
revoke all on function public.staff_calendar_in_timezone(text,date,date) from public,anon,service_role;
grant execute on function public.staff_calendar_in_timezone(text,date,date) to authenticated;

create function public.authorize_project_communication_attempt(p_id uuid,p_attempt integer) returns boolean
language plpgsql security definer set search_path='' as $$
begin
 if not exists(select 1 from public.project_communication_outbox where id=p_id and status='sending' and attempts=p_attempt) then return false;end if;
 if not public.project_communication_allowed(p_id) then
  update public.project_communication_outbox set status='cancelled',updated_at=now() where id=p_id and attempts=p_attempt;return false;
 end if;
 return true;
end;$$;
create function public.finish_project_communication_attempt(p_id uuid,p_attempt integer,p_provider_id text default null,p_error text default null) returns text
language plpgsql security definer set search_path='' as $$
declare current_attempt integer; current_status text;
begin
 select attempts,status into current_attempt,current_status from public.project_communication_outbox where id=p_id for update;
 if current_attempt is distinct from p_attempt or current_status<>'sending' then return 'not_claimed';end if;
 return public.finish_project_communication(p_id,p_provider_id,p_error);
end;$$;
revoke all on function public.authorize_project_communication_attempt(uuid,integer),public.finish_project_communication_attempt(uuid,integer,text,text) from public,anon,authenticated;
grant execute on function public.authorize_project_communication_attempt(uuid,integer),public.finish_project_communication_attempt(uuid,integer,text,text) to service_role;

create function public.client_project_request_receipt(p_request uuid,p_response uuid) returns jsonb
language plpgsql stable security definer set search_path='' as $$
declare r public.project_client_task_responses%rowtype;
begin
 if auth.uid() is null or not public.project_client_member_eligible(p_request,auth.uid()) then raise exception 'Project access required' using errcode='42501';end if;
 select * into r from public.project_client_task_responses where request_id=p_request and id=p_response and submitted_by=auth.uid();
 if r.id is null then return null;end if;
 return jsonb_build_object('id',r.id,'taskId',r.task_id,'title',coalesce((select submitted_task->>'title' from public.project_request_baselines where response_id=r.id),'Task request'),'kind',r.kind,'note',r.note,'status',r.status,'submittedAt',r.submitted_at,'reviewedAt',r.reviewed_at,'reviewNote',r.review_note);
end;$$;
revoke all on function public.client_project_request_receipt(uuid,uuid) from public,anon,service_role;
grant execute on function public.client_project_request_receipt(uuid,uuid) to authenticated;
create function public.client_request_project_access(p_request uuid) returns boolean
language sql stable security definer set search_path='' as $$select auth.uid() is not null and public.project_client_member_eligible(p_request,auth.uid());$$;
revoke all on function public.client_request_project_access(uuid) from public,anon,service_role;
grant execute on function public.client_request_project_access(uuid) to authenticated;
alter policy client_task_response_own_read on public.project_client_task_responses using(submitted_by=(select auth.uid()) and public.client_request_project_access(request_id));

create or replace function public.project_task_response_workspace(p_request uuid) returns jsonb
language plpgsql stable security definer set search_path='' as $$
declare staff boolean :=public.is_inquiry_staff(); actor uuid:=auth.uid(); policies jsonb; responses jsonb; version integer;
begin
 if actor is null or (not staff and not public.project_client_member_eligible(p_request,actor)) then
   raise exception 'Project access required' using errcode='42501'; end if;
 select revision into version from public.inquiry_projects where request_id=p_request;
 if version is null then return null;end if;
 select coalesce(jsonb_agg(jsonb_build_object(
   'taskId',c.task_id,'allowed',case when staff then true else public.client_can_respond_to_task(p_request,c.task_id,actor) end,
   'allowDecline',coalesce(p.allow_decline,false),
   'declineGuidance',coalesce(p.decline_guidance,''),'revision',coalesce(p.revision,0)
 ) order by c.task_id),'[]'::jsonb) into policies
 from public.project_task_controls c left join public.project_task_client_policies p
 on p.request_id=c.request_id and p.task_id=c.task_id
 where c.request_id=p_request and c.owner_type='client'
 and (staff or public.client_can_respond_to_task(p_request,c.task_id,actor));
 select coalesce(jsonb_agg(jsonb_build_object(
  'id',r.id,'taskId',r.task_id,'kind',r.kind,'note',r.note,'status',r.status,
  'submittedAt',r.submitted_at,'submittedBy',case when staff then r.submitted_by else null end,
  'reviewNote',r.review_note,'reviewedAt',r.reviewed_at
 ) order by r.submitted_at desc,r.id),'[]'::jsonb) into responses
 from (select * from public.project_client_task_responses
       where request_id=p_request and (staff or submitted_by=actor)
       order by submitted_at desc,id limit 150) r;
 return jsonb_build_object('projectRevision',version,'policies',policies,'responses',responses);
end;$$;

create function public.staff_project_task_communications(p_request uuid) returns table(id uuid,task_id text,status text)
language plpgsql stable security definer set search_path='' as $$
begin
 if auth.uid() is null or not public.is_inquiry_staff() then raise exception 'Staff authorization required' using errcode='42501';end if;
 return query select o.id,o.metadata->>'taskId',o.status from public.project_communication_outbox o where o.request_id=p_request and o.metadata->>'taskId' is not null;
end;$$;
revoke all on function public.staff_project_task_communications(uuid) from public,anon,service_role;
grant execute on function public.staff_project_task_communications(uuid) to authenticated;
commit;
